function setButtonBusy(button,label){if(!button||!button.isConnected)return()=>{};let old={html:button.innerHTML,disabled:button.disabled,aria:button.getAttribute("aria-label"),title:button.getAttribute("title")},compact=button.classList.contains("record-action")||!button.textContent.trim();button.disabled=true;button.setAttribute("aria-busy","true");if(compact){button.innerHTML='<span class="button-spinner" aria-hidden="true"></span>';button.setAttribute("aria-label",label);button.title=label}else button.innerHTML='<span class="button-spinner" aria-hidden="true"></span><span>'+esc(label)+'</span>';return()=>{if(!button.isConnected)return;button.innerHTML=old.html;button.disabled=old.disabled;button.removeAttribute("aria-busy");if(old.aria===null)button.removeAttribute("aria-label");else button.setAttribute("aria-label",old.aria);if(old.title===null)button.removeAttribute("title");else button.setAttribute("title",old.title)}}
const pendingFormRestores=new WeakMap();
function formBusyLabel(form,button){let id=form.id,text=(button?.textContent||"").trim().toLowerCase();if(id==="login-form")return"Signing in...";if(id==="room-form")return text.includes("add room")?"Adding room...":"Saving room...";if(id==="building-form")return text.includes("add building")?"Adding building...":"Saving building...";if(id==="schedule-form")return"Adding schedule...";if(id==="schedule-edit-form")return"Saving schedule...";if(id==="staff-form")return"Creating account...";if(id==="staff-edit-form")return"Saving account...";if(id==="check-form")return"Saving room check...";return"Saving..."}
