function confirmAction(title,description,label,danger){return new Promise(resolve=>{let accepted=false;dialog(title,description,'<p class="confirm-copy">'+esc(danger?"This action is permanent. Use Archive when you need to keep the record and its history.":"Archived records disappear from active staff workflows and can be restored later.")+'</p>','<button class="button" data-action="close">Cancel</button><button class="button '+(danger?"delete":"primary")+'" id="confirm-action" type="button">'+esc(label)+'</button>');let d=$("#dialog");d.addEventListener("close",()=>resolve(accepted),{once:true});$("#confirm-action").onclick=()=>{accepted=true;d.close()}})}
