async function archiveRecord(entity,id,archived,label,button){let verb=archived?"archive":"restore";if(archived&&!await confirmAction("Archive "+label+"?","This record will be removed from active workspace lists.","Archive",false))return;return withButtonBusy(button,(archived?"Archiving ":"Restoring ")+label.toLowerCase()+"…",async()=>{try{await api("/api/"+entity+"/"+encodeURIComponent(id),{method:"PATCH",body:JSON.stringify({archived})});await load();toast(label+(archived?" archived":" restored"),archived?"It can be restored from the Archived view.":"It is available in active workspace lists again.")}catch(error){toast("Could not "+verb+" "+label.toLowerCase(),error.message,"error")}})}
function deleteFailureMessage(error){let message=String(error?.message||"");if(/uploaded room-check photos/i.test(message))return "This account has uploaded room-check photos. Archive it to preserve those records.";if(/23503|foreign key|violates.*constraint|constraint.*violat/i.test(message))return "Other records still depend on this item. Archive it instead so check history stays intact.";return message||"The record could not be deleted."}
async function deleteEntity(entity,id,label,button){if(!await confirmAction("Delete "+label+"?","This permanently removes the record. Existing check history can prevent deletion.","Delete permanently",true))return;return withButtonBusy(button,"Deleting "+label.toLowerCase()+"…",async()=>{try{await api("/api/"+entity+"/"+encodeURIComponent(id),{method:"DELETE"});await load();toast(label+" deleted","The record was permanently removed.")}catch(error){toast("Could not delete "+label.toLowerCase(),deleteFailureMessage(error),"error")}})}function statusOf(t){if(t.issueStatus==="open")return"issue";if(t.issueStatus==="resolved")return"resolved";if(t.completedAt)return"checked";let start=new Date(t.date+"T"+t.schedule.startTime+":00+08:00").getTime(),delta=Date.now()-start;if(delta>25*60000)return"overdue";if(t.claimedBy)return"progress";return delta<0?"upcoming":"due"}
