function importForm(){s.importRows=[];let body='<div class="form-field"><div class="upload-zone">'+ico("upload")+'<strong>Choose an Excel or CSV file</strong><span>Use the template headers. Buildings and rooms must already exist.</span><input id="schedule-file" type="file" accept=".xlsx,.xls,.csv" aria-label="Choose Excel or CSV schedule file"></div><div class="fine-print" style="margin-top:8px">Columns: building, room, instructor, course, days, startTime, endTime. Section is optional.</div><div id="import-feedback"></div><div id="import-preview"></div><button type="button" class="button small" style="margin-top:10px" data-action="template">'+ico("download")+'Download Excel template</button></div>';dialog("Import schedules","Preview and validate rows before importing.",body,'<button class="button" data-action="close">Cancel</button><button class="button primary" id="confirm-import" disabled>Import schedules</button>',true);$("#schedule-file").onchange=readImport;$("#confirm-import").onclick=submitImport;$("#dialog [data-action=template]").onclick=makeTemplate}
