function parseCsv(text){let rows=[],row=[],cell="",quoted=false,source=String(text||"").replace(/^\uFEFF/,"");for(let i=0;i<source.length;i++){let c=source[i];if(quoted){if(c==='"'&&source[i+1]==='"'){cell+='"';i++}else if(c==='"')quoted=false;else cell+=c}else if(c==='"')quoted=true;else if(c===","){row.push(cell);cell=""}else if(c==="\n"){row.push(cell.replace(/\r$/, ""));rows.push(row);row=[];cell=""}else cell+=c}if(cell||row.length){row.push(cell.replace(/\r$/, ""));rows.push(row)}let headers=rows.shift()||[];return rows.filter(r=>r.some(v=>String(v).trim())).map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]||""])))}
function readImport(e){let file=e.target.files&&e.target.files[0];if(!file)return;let work=async()=>{let raw;if(window.XLSX){let wb=XLSX.read(await file.arrayBuffer(),{cellDates:true});raw=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{defval:""})}else if(file.name.toLowerCase().endsWith(".csv")){raw=parseCsv(await file.text())}else throw Error("Excel reader could not load. Use CSV or reconnect to the internet.");s.importRows=raw.map(row=>{let o={};Object.entries(row).forEach(([k,v])=>o[String(k).toLowerCase().replace(/[\s_-]+/g,"")]=v);let dayText=String(o.days||o.day||"");let days=dayText.split(/[;,|]+/).map(x=>DAY_MAP[x.trim().toLowerCase()]).filter(Number.isInteger);let normTime=v=>{if(v instanceof Date&&!Number.isNaN(v.getTime()))return String(v.getUTCHours()).padStart(2,"0")+":"+String(v.getUTCMinutes()).padStart(2,"0");if(typeof v==="number"&&v>=0&&v<1){let n=Math.round(v*1440);return String(Math.floor(n/60)).padStart(2,"0")+":"+String(n%60).padStart(2,"0")}let raw=String(v||"").trim(),match=raw.match(/^(\d{1,2}):(\d{2})(?:\s*(AM|PM))?$/i);if(!match)return raw;let h=Number(match[1]);if(match[3]?.toUpperCase()==="PM"&&h<12)h+=12;if(match[3]?.toUpperCase()==="AM"&&h===12)h=0;return String(h).padStart(2,"0")+":"+match[2]};return{building:String(o.building||"").trim(),room:String(o.room||o.roomnumber||"").trim(),instructor:String(o.instructor||"").trim(),course:String(o.course||o.class||"").trim(),section:String(o.section||"").trim(),days:days,startTime:normTime(o.starttime||o.start),endTime:normTime(o.endtime||o.end)}}).filter(x=>x.building||x.room||x.instructor||x.course);if(!s.importRows.length)throw Error("No schedule rows found.");showImportPreview()};work().catch(err=>{$("#import-feedback").innerHTML='<div class="import-error">'+esc(err.message)+"</div>"})}
function showImportPreview(){let a=s.importRows,bad=a.filter(x=>!x.building||!x.room||!x.instructor||!x.course||!x.days.length||!/^([01]\d|2[0-3]):[0-5]\d$/.test(x.startTime)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(x.endTime)||x.endTime<=x.startTime);$("#import-feedback").innerHTML=bad.length?'<div class="import-error">'+bad.length+' row(s) need required values and valid times.</div>':'<div class="import-success">'+a.length+' row(s) ready. Room and overlap checks run on import.</div>';$("#import-preview").innerHTML='<div class="import-preview"><table class="data-table"><thead><tr><th>BUILDING</th><th>ROOM</th><th>INSTRUCTOR</th><th>COURSE</th><th>DAYS</th><th>TIME</th></tr></thead><tbody>'+a.slice(0,8).map(x=>'<tr><td>'+esc(x.building)+'</td><td>'+esc(x.room)+'</td><td>'+esc(x.instructor)+'</td><td>'+esc(x.course)+'</td><td>'+esc(x.days.map(d=>DAYS[d]).join(","))+'</td><td>'+esc(x.startTime)+'–'+esc(x.endTime)+'</td></tr>').join("")+"</tbody></table></div>";$("#confirm-import").disabled=bad.length>0}
async function submitImport(){let button=$("#confirm-import");button.disabled=true;button.textContent="Importing…";try{let result=await api("/api/schedules/import",{method:"POST",body:JSON.stringify({rows:s.importRows})});$("#dialog").close();await load();toast("Schedules imported",result.imported+" rows added.")}catch(err){$("#import-feedback").innerHTML='<div class="import-error">'+esc(err.message)+(err.errors?"<br>"+err.errors.map(x=>"Row "+x.row+": "+esc(x.error)).join("<br>"):"")+"</div>";button.disabled=false;button.textContent="Import schedules"}}
function makeTemplate(){let rows=[["building","room","instructor","course","section","days","startTime","endTime"],["North Wing","201","Prof. Example","Network Administration","BSIT 3A","Mon,Wed,Fri","08:00","09:30"]];if(window.XLSX){let wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(rows),"Schedules");XLSX.writeFile(wb,"rounds-schedule-template.xlsx")}else{let a=document.createElement("a");a.href=URL.createObjectURL(new Blob([rows.map(x=>x.join(",")).join("\r\n")],{type:"text/csv"}));a.download="rounds-schedule-template.csv";a.click()}}
function checkForm(t,readonly){let old=t.check||{},photo=s.photo||old.photo||"",body='<form id="check-form"><div class="demo-banner">'+ico("building")+'<span><strong>'+esc(t.room.name)+'</strong> · '+esc(t.building.name)+' · Room '+esc(t.room.roomNumber)+'<br>'+esc(t.schedule.course)+' · '+esc(t.schedule.instructor)+'</span></div><fieldset class="check-section"><legend class="check-section-title">Is the room PC being used?</legend><div class="choice-row">'+choice("pcInUse","Yes","yes",old.pcInUse||"unknown",readonly)+choice("pcInUse","No","no",old.pcInUse||"unknown",readonly)+choice("pcInUse","Not checked","unknown",old.pcInUse||"unknown",readonly)+'</div></fieldset><fieldset class="check-section"><legend class="check-section-title">Is a personal laptop connected by HDMI?</legend><div class="choice-row">'+choice("laptopHdmi","No","no",old.laptopHdmi||"unknown",readonly)+choice("laptopHdmi","Yes","yes",old.laptopHdmi||"unknown",readonly)+choice("laptopHdmi","Not checked","unknown",old.laptopHdmi||"unknown",readonly)+'</div></fieldset><fieldset class="check-section"><legend class="check-section-title">TV or display condition</legend><div class="choice-row">'+choice("display","Looks normal","normal",old.display||"unknown",readonly)+choice("display","Needs attention","attention",old.display||"unknown",readonly)+choice("display","Damaged","damaged",old.display||"unknown",readonly)+choice("display","Not checked","unknown",old.display||"unknown",readonly)+'</div></fieldset><label class="form-field"><span class="form-label">Notes</span><textarea class="textarea" name="notes" placeholder="Add details for follow-up…">'+esc(old.notes||"")+"</textarea></label>"+(photo?'<img class="photo-preview" src="'+photo+'" alt="Room check photo">':"")+(readonly?"":'<label class="form-field" style="margin-top:12px"><span class="form-label">Add a photo (optional)</span><input id="check-photo" class="text-input" type="file" accept="image/*" capture="environment"></label>')+"</form>";let foot=readonly?'<button class="button" data-action="close">Close</button>':'<button class="button" data-action="close">Cancel</button><button class="button primary" form="check-form">Save room check</button>';dialog(readonly?"Room check":"Check room",readonly?"Saved observations and issue history.":"Record what is present. Issues remain open until an Admin resolves them.",body,foot);if(readonly){$("#check-form textarea").readOnly=true;return}$("#check-photo").onchange=async e=>{let f=e.target.files?.[0];if(!f)return;if(f.size>1800000){toast("Photo too large","Choose an image under 1.8 MB.");return}s.photo=await new Promise(resolve=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.readAsDataURL(f)});checkForm(t,false)};$("#check-form").onsubmit=async e=>{e.preventDefault();let f=new FormData(e.currentTarget);try{let saved=await api("/api/rounds/"+t.id+"/complete",{method:"POST",body:JSON.stringify({pcInUse:f.get("pcInUse"),laptopHdmi:f.get("laptopHdmi"),display:f.get("display"),notes:f.get("notes"),photo:s.photo||photo})});$("#dialog").close();await load();s.photo="";toast("Room check saved",saved.photoWarning||"The team can see this update now.")}catch(err){toast("Could not save check",err.message)}}}
function bind(){app.onclick=async e=>{let page=e.target.closest("[data-page]"),b=e.target.closest("[data-action]");if(page){if(page.dataset.page==="more"){s.more=!s.more;s.menu=false;return render()}if(!nav().some(x=>x[0]===page.dataset.page))return;s.more=false;s.page=page.dataset.page;return render()}if(!b)return;let a=b.dataset.action,id=b.dataset.id,t=tasks().find(x=>x.id===id);try{if(a==="archive-view"){let kind=b.dataset.kind;if(s.archiveView[kind]){s.archiveView[kind]=b.dataset.view;if(kind==="schedules")s.lists.schedules.state="all";return render()}}if(a==="record-edit"){if(b.dataset.entity==="buildings")return buildingForm(id);if(b.dataset.entity==="rooms")return roomForm(null,id);if(b.dataset.entity==="users")return staffForm(id)}if(a==="record-archive"||a==="record-restore")return archiveRecord(b.dataset.entity,id,a==="record-archive",archiveEntityName(b.dataset.entity),b);if(a==="record-delete")return deleteEntity(b.dataset.entity,id,archiveEntityName(b.dataset.entity),b);if(a==="list-reset"&&listDefaults[b.dataset.list]){s.lists[b.dataset.list]={...listDefaults[b.dataset.list]};return render()}if(a==="close-more"){s.more=false;return render()}if(a==="schedule")return scheduleForm();if(a==="edit-schedule")return editScheduleForm(id);if(a==="toggle-schedule"){let item=s.data.schedules.find(x=>x.id===id);if(!item)return;await api("/api/schedules/"+encodeURIComponent(id),{method:"PUT",body:JSON.stringify({...item,active:!item.active})});await load();return toast(item.active?"Schedule paused":"Schedule resumed",item.active?"No new handoff checks will be created.":"Handoff checks will use this schedule.")}if(a==="building")return buildingForm();if(a==="room")return roomForm(b.dataset.building);if(a==="staff")return staffForm();if(a==="import")return importForm();if(a==="template")return makeTemplate();if(a==="dismiss"){localStorage.setItem("rounds-hide-demo","1");return render()}if(a==="notice"){s.notice=!s.notice;s.menu=false;return render()}if(a==="menu"){s.menu=!s.menu;s.notice=false;return render()}if(a==="close")return $("#dialog").close();if(a==="logout"){await api("/api/logout",{method:"POST",body:"{}"});events?.close();window.roundsSupabase?.unsubscribe();s.live=false;s.menu=false;s.more=false;s.alertStatusSignature=null;s.user=null;s.data=null;return login("")}if(a==="check"&&t){if(!t.claimedBy){await api("/api/rounds/"+id+"/claim",{method:"POST",body:"{}"});await load();t=tasks().find(x=>x.id===id);toast("Room check claimed","This room is marked in progress for you.")}s.photo="";return checkForm(t,false)}if(a==="view"&&t){s.photo="";return checkForm(t,true)}if(a==="history-view"){s.photo="";let record=await api("/api/rounds/"+encodeURIComponent(id));return checkForm(record.round,true)}if(a==="resolve"&&t){await api("/api/rounds/"+id+"/resolve",{method:"POST",body:"{}"});await load();return toast("Issue resolved","The round history remains available.")}}catch(err){toast("Could not complete action",err.message)}};
app.oninput=updateListControl;app.onchange=updateListControl}
async function load(){let previous=s.data?.audit?new Set(s.data.audit.map(x=>String(x.id))):null;s.refreshPending=false;s.data=await api("/api/state?date="+today());s.user=s.data.user;if(s.alertStatusSignature===null)s.alertStatusSignature=statusSignature();let incoming=previous?s.data.audit.filter(x=>!previous.has(String(x.id))&&x.actorId!==s.user.id):[];render();if(incoming.length){let latest=incoming[0];if(incoming.length>1)toast("New workspace activity",incoming.length+" changes · latest: "+latest.action+" · "+latest.detail);else toast(latest.action,latest.detail+" · "+latest.actor)}}
function updateTimeSensitiveStatuses(){if(!s.user||!s.data||$("#dialog")?.open)return;let current=statusSignature(),previous=s.alertStatusSignature;if(previous===null){s.alertStatusSignature=current;return}if(current===previous)return;let old=new Map(previous.split("|").filter(Boolean).map(part=>{let i=part.lastIndexOf(":");return[part.slice(0,i),part.slice(i+1)]})),newHandoffs=tasks().filter(t=>["upcoming",undefined].includes(old.get(t.id))&&statusOf(t)==="due"),newOverdue=tasks().filter(t=>["upcoming","due","progress",undefined].includes(old.get(t.id))&&statusOf(t)==="overdue");if(newHandoffs.length===1){let t=newHandoffs[0];toast("Room round due",t.room.name+" · "+t.schedule.instructor)}else if(newHandoffs.length>1)toast("Room rounds due",newHandoffs.length+" instructor handoffs need a check.");if(newOverdue.length===1){let t=newOverdue[0];toast("Room check overdue",t.room.name+" · "+t.schedule.instructor)}else if(newOverdue.length>1)toast("Room checks overdue",newOverdue.length+" handoffs still need a check.");s.alertStatusSignature=current;let focus=document.activeElement,focusId=focus?.id,page=focus?.dataset?.page,action=focus?.dataset?.action,actionId=focus?.dataset?.id,selection=focus&&"selectionStart" in focus?focus.selectionStart:null,scroll=window.scrollY;render();window.scrollTo(0,scroll);let target=focusId?document.getElementById(focusId):page?document.querySelector('[data-page="'+page+'"]'):action?document.querySelector('[data-action="'+action+'"]'+(actionId?'[data-id="'+actionId+'"]':'')):null;if(target){target.focus();if(selection!==null&&target.setSelectionRange)target.setSelectionRange(selection,selection)}}
let events;function connect(){events?.close();if(window.roundsSupabase){window.roundsSupabase.subscribe(()=>{if($("#dialog")?.open){s.refreshPending=true;return}load().catch(()=>{})},online=>{if(s.live!==online){s.live=online;render()}});return}events=new EventSource("/api/events");events.onopen=()=>{if(!s.live){s.live=true;render()}};events.onerror=()=>{if(s.live){s.live=false;render()}};events.addEventListener("update",()=>{if($("#dialog")?.open){s.refreshPending=true;return}load().catch(()=>{})})}
async function boot(){try{let r=await api("/api/session");if(r.user){s.user=r.user;await load();connect()}else login("")}catch(e){app.innerHTML='<main class="login-shell"><section class="login-story"><div class="login-story-content"><h1 class="login-heading">Rounds is offline.</h1><p class="login-story-copy">'+esc(e.message)+' Check the Supabase configuration and internet connection, then refresh.</p></div></section></main>'}}
document.addEventListener("click",e=>{if(e.target.closest("[data-action=theme]")){toggleTheme();return}if(!e.target.closest(".relative")&&(s.menu||s.notice)){s.menu=false;s.notice=false;render()}});
document.addEventListener("submit",async e=>{if(e.defaultPrevented)return;let form=e.target;if(!["schedule-form","building-form","room-form","staff-form"].includes(form.id))return;e.preventDefault();let f=new FormData(form);try{if(form.id==="schedule-form"){await api("/api/schedules",{method:"POST",body:JSON.stringify({roomId:f.get("roomId"),instructor:f.get("instructor"),course:f.get("course"),section:f.get("section"),startTime:f.get("startTime"),endTime:f.get("endTime"),days:f.getAll("days").map(Number)})})}else if(form.id==="building-form"){await api("/api/buildings",{method:"POST",body:JSON.stringify(Object.fromEntries(f))})}else if(form.id==="room-form"){await api("/api/rooms",{method:"POST",body:JSON.stringify(Object.fromEntries(f))})}else{await api("/api/users",{method:"POST",body:JSON.stringify(Object.fromEntries(f))})}$("#dialog").close();await load();toast(form.id==="schedule-form"?"Schedule added":form.id==="building-form"?"Building added":form.id==="room-form"?"Room added":"IT Staff account created")}catch(err){toast("Could not save",err.message)}});
boot();setInterval(updateTimeSensitiveStatuses,15000);
